package org.eclipse.kura.core.configuration;

import static org.junit.Assert.assertTrue;

import java.util.Optional;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

import org.eclipse.kura.core.testutil.service.ServiceUtil;

final class WaitUtil {

    private static final long TIMEOUT_MS = 30000;
    private static final long POLL_INTERVAL_MS = 100;

    private WaitUtil() {
    }

    static <T> T waitForService(final Class<T> service) throws Exception {
        return ServiceUtil.trackService(service, Optional.empty()).get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
    }

    static void waitUntil(final String description, final BooleanSupplier condition) {
        final long deadline = System.currentTimeMillis() + TIMEOUT_MS;

        while (!condition.getAsBoolean() && System.currentTimeMillis() < deadline) {
            try {
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        assertTrue(description, condition.getAsBoolean());
    }
}
